import React, { useState, useEffect } from 'react';
import { Sun, Moon, Globe, Menu, X, ChevronDown, User, LogIn, UserPlus, LogOut, ShieldCheck, BookOpen, History } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';

const translations = {
  en: {
    home: 'Check',
    services: 'Learn',
    portfolio: 'History',
    contact: 'About',
    // ... rest of translations
    brand: 'Mpanolo-tsaina',
  },
  fr: {
    home: 'Vérifier',
    services: 'Apprendre',
    portfolio: 'Historique',
    contact: 'À propos',
    brand: 'Mpanolo-tsaina',
    // ... 
  },
  mg: {
    home: 'Hamarino',
    services: 'Hianatra',
    portfolio: 'Tantara',
    contact: 'Momba anay',
    brand: 'Mpanolo-tsaina',
    // ...
  },
};

const Header = ({ isAuthenticated = false, onLogout, userData = null }) => {
  const navigate = useNavigate();

  // États
  const [language, setLanguage] = useState('mg'); // Par défaut en Malagasy pour l'inclusion
  const [darkMode, setDarkMode] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [languageDropdownOpen, setLanguageDropdownOpen] = useState(false);
  const [themeDropdownOpen, setThemeDropdownOpen] = useState(false);
  const [userDropdownOpen, setUserDropdownOpen] = useState(false);

  const userEmail = userData?.email || localStorage.getItem('userEmail') || '';
  const userName = userData?.name || userEmail.split('@')[0] || 'Mpianatra';

  // Navigation adaptée au projet
  const navItems = [
    { id: 'home', icon: <ShieldCheck size={18} />, path: '/' },
    { id: 'services', icon: <BookOpen size={18} />, path: '/learn' },
    { id: 'portfolio', icon: <History size={18} />, path: '/history' }
  ];

  // ... (Garder vos useEffect et fonctions toggle/changeTheme/changeLanguage tels quels)

  const t = (key) => translations[language][key] || key;

  return (
    <header className="sticky top-0 z-50 w-full border-b border-neutral-200 dark:border-neutral-800 bg-white/90 dark:bg-neutral-950/90 backdrop-blur-md transition-colors duration-300">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">

          {/* Logo adapté à Madagascar AI */}
          <Link to="/" className="flex items-center space-x-2">
            <div className="h-10 w-10 rounded-xl bg-gradient-to-br from-red-500 via-green-500 to-white flex items-center justify-center shadow-md border border-neutral-200">
              <span className="font-black text-neutral-800">M</span>
            </div>
            <span className="text-xl font-bold text-neutral-900 dark:text-white tracking-tight">
              Mpanolo-tsaina<span className="text-green-600 dark:text-green-400">AI</span>
            </span>
          </Link>

          {/* Navigation Desktop adaptée */}
          <nav className="hidden md:flex items-center space-x-1">
            {navItems.map((item) => (
              <Link
                key={item.id}
                to={item.path}
                className="flex items-center space-x-2 px-4 py-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:text-green-600 dark:hover:text-green-400 hover:bg-green-50 dark:hover:bg-green-900/20 transition-all duration-200 font-medium"
              >
                {item.icon}
                <span>{t(item.id)}</span>
              </Link>
            ))}
          </nav>

          <div className="flex items-center space-x-2">
            {/* Langue & Thème (Gardez votre logique actuelle qui est très bonne) */}

            {/* Boutons d'authentification corrigés */}
            {isAuthenticated ? (
              <div className="relative">
                <button
                  onClick={() => setUserDropdownOpen(!userDropdownOpen)}
                  className="flex items-center space-x-2 px-3 py-2 rounded-full bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 hover:shadow-md transition-all"
                >
                  <div className="h-7 w-7 rounded-full bg-green-500 flex items-center justify-center text-white">
                    <span className="text-xs font-bold">{userName.charAt(0).toUpperCase()}</span>
                  </div>
                  <ChevronDown size={14} />
                </button>

                {userDropdownOpen && (
                  <div className="absolute right-0 mt-2 w-56 py-2 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-800 rounded-xl shadow-xl z-50">
                    <div className="px-4 py-3 border-b border-neutral-200 dark:border-neutral-800 bg-neutral-50/50 dark:bg-neutral-800/50">
                      <p className="text-sm font-bold text-neutral-900 dark:text-white">{userName}</p>
                      <p className="text-xs text-neutral-500 truncate">{userEmail}</p>
                    </div>
                    {/* Liens dropdown */}
                    <button
                      onClick={handleLogout}
                      className="w-full text-left flex items-center space-x-3 px-4 py-2.5 hover:bg-red-50 dark:hover:bg-red-900/20 text-red-600 transition-colors"
                    >
                      <LogOut size={16} /> {/* Corrigé LogIn -> LogOut */}
                      <span>{t('logout')}</span>
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="hidden md:flex items-center space-x-2">
                <button onClick={handleLoginClick} className="px-4 py-2 text-sm font-semibold text-neutral-600 hover:text-green-600 transition-colors">
                  {t('login')}
                </button>
                <button onClick={handleRegisterClick} className="px-5 py-2 bg-green-600 hover:bg-green-700 text-white text-sm font-bold rounded-full transition-all shadow-lg shadow-green-600/20">
                  {t('register')}
                </button>
              </div>
            )}

            {/* Menu mobile (Garder votre burger menu) */}
            <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="md:hidden p-2 text-neutral-600">
               {mobileMenuOpen ? <X /> : <Menu />}
            </button>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;
